-- generated by desktop-set (Settings > Dock, Settings > Widgets, Settings > Gaming)
hl.layer_rule({
    name  = "rice-dock-blur",
    match = { namespace = "rice-dock" },
    blur = true,
    ignore_alpha = 0.1,
})
hl.layer_rule({
    name  = "rice-deskmenu-blur",
    match = { namespace = "rice-deskmenu" },
    blur = true,
    ignore_alpha = 0.3,
    no_anim = true,
})
hl.layer_rule({
    name  = "rice-gamebar-blur",
    match = { namespace = "rice-gamebar" },
    blur = true,
    ignore_alpha = 0.3,
})
hl.layer_rule({
    name  = "rice-widget-blur",
    match = { namespace = "rice-widget" },
    blur = true,
    ignore_alpha = 0.2,
})
